{
  "name": "X-keys 可编程按键面板",
  "name_en": "X-keys Programmable Keypad",
  "manufacturer": "PI Engineering",
  "description": "一类通过 USB HID 连接的物理按键控制面板，可读取按键状态，并控制状态指示灯与按键背光。适合在实验系统中用作人工触发、模式切换、状态显示和自定义快捷控制界面。",
  "description_en": "A physical USB HID keypad/control panel that can read button states and control status LEDs and key backlighting. It is suitable for manual triggering, mode switching, status indication, and custom shortcut control in laboratory setups.",
  "tag_hints": [
    "programmable keypad",
    "USB HID",
    "manual experiment control",
    "button state input",
    "LED backlight control",
    "status indicator LEDs",
    "control panel"
  ],
  "actions": [
    {
      "action_name": "auto-getState",
      "description": "获取设备当前状态，可选择从硬件刷新按键状态。",
      "description_en": "Get the current device state, optionally refreshing button state from the hardware."
    },
    {
      "action_name": "auto-setCallback",
      "description": "设置设备状态变化时触发的回调函数。",
      "description_en": "Set a callback to be invoked when the device state changes."
    },
    {
      "action_name": "auto-setLED",
      "description": "设置设备状态指示灯。",
      "description_en": "Set the device status LEDs."
    },
    {
      "action_name": "auto-setIntensity",
      "description": "设置背光亮度强度。",
      "description_en": "Set the backlight intensity."
    },
    {
      "action_name": "auto-setBacklights",
      "description": "设置所有按键背光状态。",
      "description_en": "Set the backlight state of all keys."
    },
    {
      "action_name": "auto-setBacklight",
      "description": "设置指定按键、行或列的背光状态。",
      "description_en": "Set the backlight state of a specific key, row, or column."
    },
    {
      "action_name": "auto-setBacklightRows",
      "description": "设置按键各行的背光状态。",
      "description_en": "Set the backlight state for key rows."
    },
    {
      "action_name": "auto-close",
      "description": "关闭设备并停止事件处理线程。",
      "description_en": "Close the device and stop its event handling thread."
    }
  ]
}

